function FOURIER_IWT(y):
    n <- length(y);  w <- weight(y)
    return (1+i)^(n-w) * (1-i)^w

function FOURIER_IWT_DOUBLY_EVEN(y):         # requires 4 | weight(y)
    # uses 1-i = (-i)(1+i) and (-i)^(4k) = 1
    return (1+i)^length(y)

