function EIGHT_DIVIDES_FROM_POSITIVITY(n, value):
    # value = (1+i)^n is asserted to be a positive real
    is_pos_real <- (Im(value) ~ 0) and (Re(value) > 0)
    return is_pos_real and (n mod 8 == 0)

function DEDUCE_LENGTH_MOD8(n):
    z <- (1+i)^(n mod 8)
    table <- { (1+i)^r : r  for r in 0..7 }
    return r such that table[r] == z   # 0 means 8 | n

